SELECT b.id AS subj_id, b.code AS subj_code, b.name AS subj_name, COALESCE(b.intro, '') AS subj_intro, COALESCE(a.persona, '') AS subj_persona, CASE b.kind WHEN 'language' THEN '语言' ELSE '通用' END AS subj_kind, COALESCE(NULLIF(TRIM(b.levels), ''), 'N5,N4,N3,N2,N1') AS subj_levels, CASE b.visibility WHEN 'public' THEN '公共' ELSE '私有' END AS subj_visibility, CASE b.status WHEN 'active' THEN '启用' WHEN 'disabled' THEN '停用' ELSE '草稿' END AS subj_status, b.owner AS subj_owner, CASE b.m WHEN 'owner' THEN '负责' WHEN 'editor' THEN '协作' WHEN 'public' THEN '公共只读' ELSE '单人' END AS subj_my_role, b.sn AS subj_student_n, b.tn AS subj_teacher_n, CASE WHEN b.m IN ('owner', 'single') THEN 1 ELSE 0 END AS can_manage, CASE WHEN b.status <> 'disabled' THEN 1 ELSE 0 END AS can_assign FROM (SELECT i.id AS id, i.code AS code, i.name AS name, i.intro AS intro, i.kind AS kind, i.levels AS levels, i.visibility AS visibility, i.status AS status, i.owner AS owner, CASE WHEN i.owner = :learner OR EXISTS (SELECT 1 FROM subject_teacher t WHERE t.subject_id = i.id AND t.teacher = :learner AND t.role = 'owner') THEN 'owner' WHEN EXISTS (SELECT 1 FROM subject_teacher t WHERE t.subject_id = i.id AND t.teacher = :learner) THEN 'editor' ELSE 'public' END AS m, (SELECT COUNT(*) FROM subject_student s WHERE s.subject_id = i.id AND s.status = 'active') AS sn, (CASE WHEN i.owner <> '' THEN 1 ELSE 0 END) + (SELECT COUNT(*) FROM subject_teacher t2 WHERE t2.subject_id = i.id AND t2.teacher <> i.owner) AS tn FROM subject_info i WHERE i.owner = :learner OR i.id IN (SELECT subject_id FROM subject_teacher WHERE teacher = :learner) OR (i.visibility = 'public' AND i.status <> 'draft')) b LEFT JOIN subject_ai a ON a.subject_id = b.id ORDER BY b.id
